import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    static class Line {
        long y1, y2;
        int rank;

        Line(long y1, long y2) {
            this.y1 = y1;
            this.y2 = y2;
        }
    }

    static class Fenwick {
        long[] tree;

        Fenwick(int n) {
            tree = new long[n + 1];
        }

        void add(int index) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i]++;
            }
        }

        long sum(int index) {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i) {
                result += tree[i];
            }
            return result;
        }
    }

    static int lowerBound(long[] a, int size, long value) {
        int left = 0, right = size;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (a[mid] < value) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = (int) fs.nextLong();
        long x1 = fs.nextLong();
        long x2 = fs.nextLong();

        Line[] lines = new Line[n];
        long[] y2Values = new long[n];

        for (int i = 0; i < n; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();
            long y1 = a * x1 + b;
            long y2 = a * x2 + b;
            lines[i] = new Line(y1, y2);
            y2Values[i] = y2;
        }

        Arrays.sort(lines, (a, b) -> Long.compare(a.y1, b.y1));
        Arrays.sort(y2Values);

        int unique = 0;
        for (long value : y2Values) {
            if (unique == 0 || y2Values[unique - 1] != value) {
                y2Values[unique++] = value;
            }
        }

        for (Line line : lines) {
            line.rank = lowerBound(y2Values, unique, line.y2) + 1;
        }

        Fenwick fenwick = new Fenwick(unique);
        long answer = 0;
        long seen = 0;

        for (int left = 0; left < n; ) {
            int right = left + 1;
            while (right < n && lines[right].y1 == lines[left].y1) right++;

            int groupSize = right - left;
            answer += (long) groupSize * (groupSize - 1) / 2;

            for (int i = left; i < right; i++) {
                int rank = lines[i].rank;
                answer += seen - fenwick.sum(rank - 1);
            }

            for (int i = left; i < right; i++) {
                fenwick.add(lines[i].rank);
            }

            seen += groupSize;
            left = right;
        }

        System.out.println(answer);
    }
}
